"""Repeat concise output-contract cues from the live query after its references."""

import json
import re
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_MAX_CONTEXT_CHARS = 30000
_MAX_STORED_EXAMPLES = 512
_DIRECTIVE_RE = re.compile(
    r"\b(format|output|answer|respond|return|exact|json|serialize|delimiter|"
    r"separated|must|should|between)\b",
    re.IGNORECASE,
)
_MARKUP_RE = re.compile(r"(?<!\w)(?:\[[^\]\r\n]{1,48}\]|<[^>\r\n]{1,48}>)")

_PROMPT = """The references are labeled examples. Use them to reason about the current
problem, while following the current problem's own requirements.

{examples}

**Current problem:**
{input}

**Output-contract cues quoted from the current problem:**
{contract}

Use these cues to preserve any requested wrapper, separator, serialization, or
answer format. They summarize the current problem and do not change its meaning.
Return one JSON object with "reasoning" and "final_answer" fields; put the
requested answer in final_answer exactly as the current problem requires.
"""


def _question_from_result(result: dict[str, Any]) -> str:
    metadata = result.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    value = result.get("raw_question") or metadata.get("raw_question")
    return str(value if value is not None else result.get("input", ""))


def _output_cues(text: str) -> str:
    cues: list[str] = []
    seen: set[str] = set()
    lines = text.splitlines()
    for line in lines:
        stripped = line.strip()
        if stripped and len(stripped) <= 700 and _DIRECTIVE_RE.search(stripped):
            cue = stripped[:600]
            if cue not in seen:
                cues.append(cue)
                seen.add(cue)
    for line in lines:
        if len(line) > 1600:
            continue
        markers = list(_MARKUP_RE.finditer(line))
        if len(markers) < 2:
            continue
        cue = line.strip()[:600]
        if cue and cue not in seen:
            cues.append(cue)
            seen.add(cue)
    return "\n".join(cues[:8]) or "Follow the output format stated in the current problem."


class AnswerContractCues(MemorySystem):
    """Retain broad examples and restate current-query formatting cues at the end."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self._last_context_chars = 0

    def _format_examples(self) -> str:
        parts: list[str] = []
        used = 0
        for index, item in enumerate(self.examples, start=1):
            part = (
                f"Reference {index}\nProblem: {item['question']}\n"
                f"Expected answer: {item['target']}"
            )
            added = len(part) + (2 if parts else 0)
            if used + added > _MAX_CONTEXT_CHARS:
                break
            parts.append(part)
            used += added
        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples = self._format_examples() or "No references yet."
        contract = _output_cues(input)
        self._last_context_chars = len(examples) + len(contract)
        response = self.call_llm(
            _PROMPT.format(examples=examples, input=input, contract=contract)
        )
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_examples": examples.count("Reference "),
            "num_contract_cues": len(contract.splitlines()),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        seen = {(item["question"], item["target"]) for item in self.examples}
        for result in batch_results:
            item = {
                "question": _question_from_result(result),
                "target": str(result.get("ground_truth", "")),
            }
            key = (item["question"], item["target"])
            if key not in seen:
                self.examples.append(item)
                seen.add(key)
        self.examples = self.examples[-_MAX_STORED_EXAMPLES:]
        self._last_context_chars = 0

    def get_context_length(self) -> int:
        return self._last_context_chars or len(self._format_examples())

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = [
            {"question": str(item.get("question", "")), "target": str(item.get("target", ""))}
            for item in data.get("examples", [])
        ][-_MAX_STORED_EXAMPLES:]
        self._last_context_chars = 0
"""Adapt example-set breadth to the strength of the nearest lexical match."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

_TOKEN_RE = re.compile(r"\w+|[^\w\s]", re.UNICODE)
_PROMPT = """The references are labeled examples with different degrees of
relevance. Treat close matches as stronger evidence and broad matches only as
background. Similar wording does not replace checking the current details.

{examples}

**Current problem and its instructions:**
{input}

Return one JSON object with "reasoning" and "final_answer" fields. Follow the
current problem's answer format.
"""


def _question(result: dict[str, Any]) -> str:
    metadata = result.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(result.get("raw_question") or metadata.get("raw_question") or result.get("input", ""))


def _features(text: str) -> Counter[str]:
    tokens = [x.lower() for x in _TOKEN_RE.findall(text)]
    result: Counter[str] = Counter("w:" + x for x in tokens)
    for token in tokens:
        result.update("c:" + token[i:i+3] for i in range(max(0, len(token) - 2)))
    return result


def _vector(features: Counter[str], df: Counter[str], n: int) -> dict[str, float]:
    raw = {k: (1 + math.log(c)) * (1 + math.log((n + 1) / (df[k] + 1))) for k, c in features.items()}
    norm = math.sqrt(sum(v * v for v in raw.values())) or 1.0
    return {k: v / norm for k, v in raw.items()}


class ConfidenceAdaptiveMemory(MemorySystem):
    """Use a narrow neighborhood for confident matches and broaden uncertain ones."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self._last_context_chars = 0

    def _ranked(self, query: str) -> list[tuple[float, int, dict[str, str]]]:
        if not self.examples:
            return []
        docs = [_features(x["question"]) for x in self.examples]
        df: Counter[str] = Counter()
        for doc in docs:
            df.update(doc.keys())
        q = _vector(_features(query), df, len(docs))
        ranked = []
        for i, (item, doc) in enumerate(zip(self.examples, docs)):
            d = _vector(doc, df, len(docs))
            ranked.append((sum(v * d.get(k, 0.0) for k, v in q.items()), i, item))
        return sorted(ranked, key=lambda x: (-x[0], x[1]))

    def _select(self, query: str) -> list[tuple[float, int, dict[str, str]]]:
        ranked = self._ranked(query)
        if not ranked:
            return []
        top = ranked[0][0]
        runner_up = ranked[1][0] if len(ranked) > 1 else 0.0
        margin = top - runner_up
        # Scores are normalized cosine similarities; a weak or ambiguous top match
        # triggers a broader evidence set. Strong matches keep context compact.
        limit = 4 if top >= 0.32 and margin >= 0.06 else (8 if top >= 0.18 else 12)
        return ranked[:limit]

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        selected = self._select(input)
        parts = [f"Reference {i} (similarity {score:.3f})\nProblem: {item['question']}\nExpected answer: {item['target']}" for i, (score, _, item) in enumerate(selected, 1)]
        examples = "\n\n".join(parts) or "No references yet."
        self._last_context_chars = len(examples)
        response = self.call_llm(_PROMPT.format(examples=examples, input=input))
        top_score = selected[0][0] if selected else 0.0
        return extract_json_field(response, "final_answer"), {"full_response": response, "num_examples": len(parts), "top_similarity": top_score}

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        seen = {(x["question"], x["target"]) for x in self.examples}
        for result in batch_results:
            item = {"question": _question(result), "target": str(result.get("ground_truth", ""))}
            key = (item["question"], item["target"])
            if key not in seen:
                self.examples.append(item)
                seen.add(key)
        self.examples = self.examples[-512:]
        self._last_context_chars = 0

    def get_context_length(self) -> int:
        return self._last_context_chars or sum(len(x["question"]) + len(x["target"]) + 36 for x in self.examples[-12:])

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = [{"question": str(x.get("question", "")), "target": str(x.get("target", ""))} for x in data.get("examples", [])][-512:]
        self._last_context_chars = 0
"""Learn close, differently labeled examples as contrastive reference pairs."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_WORD_RE = re.compile(r"\w+", re.UNICODE)
_RUN_RE = re.compile(r"[^\W_]+", re.UNICODE)
_MAX_EXAMPLES = 4
_MAX_CONTEXT_CHARS = 9000
_MAX_STORED_EXAMPLES = 320
_PROMPT = """The reference sets below contain two separate labeled examples with
similar wording but different expected answers. They are contrastive evidence:
compare the details that distinguish the cases. Neither answer is a guess for the
current problem, and neither reference changes the current problem's instructions.

{references}

**Current problem and its instructions:**
{input}

Return one JSON object with "reasoning" and "final_answer" fields. Follow the
current problem's requested answer format exactly.
"""


def _question_from_result(result: dict[str, Any]) -> str:
    metadata = result.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    value = result.get("raw_question") or metadata.get("raw_question")
    return str(value if value is not None else result.get("input", ""))


def _features(text: str) -> Counter[str]:
    lowered = text.lower()
    counts: Counter[str] = Counter("w:" + token for token in _WORD_RE.findall(lowered))
    for run in _RUN_RE.findall(lowered):
        compact = "".join(ch for ch in run if ch.isalnum())
        for size in (2, 3):
            counts.update("c:" + compact[i : i + size] for i in range(len(compact) - size + 1))
    return counts


def _vectorize(
    features: Counter[str], document_frequency: Counter[str], total_docs: int
) -> dict[str, float]:
    values = {
        key: (1.0 + math.log(count))
        * (math.log((total_docs + 1.0) / (document_frequency.get(key, 0) + 1.0)) + 1.0)
        for key, count in features.items()
    }
    norm = math.sqrt(sum(value * value for value in values.values())) or 1.0
    return {key: value / norm for key, value in values.items()}


def _cosine(left: dict[str, float], right: dict[str, float]) -> float:
    if len(left) > len(right):
        left, right = right, left
    return sum(value * right.get(key, 0.0) for key, value in left.items())


class ContrastiveBoundaryMemory(MemorySystem):
    """Mine nearest different-target pairs from observed labels, not model errors."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self.pairs: list[dict[str, Any]] = []
        self._last_context_chars = 0

    def _rebuild_pairs(self) -> None:
        if len(self.examples) < 2:
            self.pairs = []
            return
        docs = [_features(item["question"]) for item in self.examples]
        document_frequency: Counter[str] = Counter()
        for doc in docs:
            document_frequency.update(doc.keys())
        vectors = [_vectorize(doc, document_frequency, len(docs)) for doc in docs]
        best_pairs: dict[tuple[int, int], float] = {}
        for left_index, left in enumerate(self.examples):
            nearest_index = -1
            nearest_score = -1.0
            for right_index, right in enumerate(self.examples):
                if left_index == right_index or left["target"] == right["target"]:
                    continue
                similarity = _cosine(vectors[left_index], vectors[right_index])
                if similarity > nearest_score:
                    nearest_index, nearest_score = right_index, similarity
            if nearest_index < 0 or nearest_score < 0.035:
                continue
            key = tuple(sorted((left_index, nearest_index)))
            best_pairs[key] = max(best_pairs.get(key, 0.0), nearest_score)
        ordered = sorted(best_pairs.items(), key=lambda item: (-item[1], item[0]))[:256]
        self.pairs = [
            {"left": left, "right": right, "similarity": score}
            for (left, right), score in ordered
        ]

    def _ranked_pairs(self, query: str) -> list[tuple[float, dict[str, Any]]]:
        if not self.examples:
            return []
        docs = [_features(item["question"]) for item in self.examples]
        document_frequency: Counter[str] = Counter()
        for doc in docs:
            document_frequency.update(doc.keys())
        query_vector = _vectorize(_features(query), document_frequency, len(docs))
        vectors = [_vectorize(doc, document_frequency, len(docs)) for doc in docs]
        similarities = [_cosine(query_vector, vector) for vector in vectors]
        if not self.pairs:
            fallback = sorted(
                range(len(self.examples)), key=lambda index: (-similarities[index], index)
            )[:_MAX_EXAMPLES]
            return [
                (similarities[index], {"single": self.examples[index]}) for index in fallback
            ]

        ranked: list[tuple[float, dict[str, Any]]] = []
        for pair in self.pairs:
            left_index, right_index = int(pair["left"]), int(pair["right"])
            left_sim, right_sim = similarities[left_index], similarities[right_index]
            score = 0.78 * max(left_sim, right_sim) + 0.22 * min(left_sim, right_sim)
            ranked.append((score, pair))
        chosen: list[tuple[float, dict[str, Any]]] = []
        used_examples: set[int] = set()
        remaining = list(ranked)
        while remaining and len(chosen) < _MAX_EXAMPLES:
            def adjusted_score(item: tuple[float, dict[str, Any]]) -> float:
                score, pair = item
                endpoints = {int(pair["left"]), int(pair["right"])}
                overlap = len(endpoints & used_examples)
                return score - 0.12 * overlap

            best = max(
                remaining,
                key=lambda item: (
                    adjusted_score(item),
                    float(item[1]["similarity"]),
                    -int(item[1]["left"]),
                ),
            )
            remaining.remove(best)
            score, pair = best
            endpoints = {int(pair["left"]), int(pair["right"])}
            chosen.append((adjusted_score(best), pair))
            used_examples.update(endpoints)
        return chosen

    def _format_references(self, query: str) -> str:
        parts: list[str] = []
        used = 0
        for rank, (score, pair) in enumerate(self._ranked_pairs(query), start=1):
            if "single" in pair:
                item = pair["single"]
                part = (
                    f"Reference {rank}\nProblem: {item['question']}\n"
                    f"Expected answer: {item['target']}"
                )
            else:
                left = self.examples[int(pair["left"])]
                right = self.examples[int(pair["right"])]
                part = (
                    f"Contrast set {rank} (query relevance {score:.3f})\n"
                    f"Case A: {left['question']}\nExpected answer: {left['target']}\n"
                    f"Case B: {right['question']}\nExpected answer: {right['target']}"
                )
            added = len(part) + (2 if parts else 0)
            if used + added > _MAX_CONTEXT_CHARS:
                continue
            parts.append(part)
            used += added
        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        references = self._format_references(input)
        self._last_context_chars = len(references)
        response = self.call_llm(
            _PROMPT.format(references=references or "No references yet.", input=input)
        )
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "num_contrast_sets": references.count("Contrast set "),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        seen = {(item["question"], item["target"]) for item in self.examples}
        for result in batch_results:
            item = {
                "question": _question_from_result(result),
                "target": str(result.get("ground_truth", "")),
            }
            key = (item["question"], item["target"])
            if key not in seen:
                self.examples.append(item)
                seen.add(key)
        self.examples = self.examples[-_MAX_STORED_EXAMPLES:]
        self._rebuild_pairs()
        self._last_context_chars = 0

    def get_context_length(self) -> int:
        return self._last_context_chars or len(self._format_references(""))

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = [
            {"question": str(item.get("question", "")), "target": str(item.get("target", ""))}
            for item in data.get("examples", [])
        ][-_MAX_STORED_EXAMPLES:]
        self._rebuild_pairs()
        self._last_context_chars = 0
"""Compact repeated demonstrations while preserving answer coverage."""

import json
import re
from collections import defaultdict
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_WORD_RE = re.compile(r"\w+", re.UNICODE)
_MAX_EXAMPLES = 48
_MAX_CONTEXT_CHARS = 12000
_PROMPT = """The references below are examples of input and target-answer pairs.
Use them as broad evidence, while following the current problem's own
instructions and exact answer format. Examples never override the current
problem.

{examples}

**Current problem and its instructions:**
{input}

Return one JSON object with exactly the fields "reasoning" and "final_answer".
The final_answer must obey the current problem's requested format.
"""


def _question_from_result(result: dict[str, Any]) -> str:
    metadata = result.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    value = result.get("raw_question") or metadata.get("raw_question")
    return str(value if value is not None else result.get("input", ""))


def _signature(text: str) -> set[str]:
    lowered = text.lower()
    units = {"w:" + token for token in _WORD_RE.findall(lowered)}
    for run in re.findall(r"[^\W_]+", lowered, re.UNICODE):
        compact = "".join(ch for ch in run if ch.isalnum())
        units.update("c:" + compact[i : i + 2] for i in range(max(0, len(compact) - 1)))
    return units


class CoverageBalancedMemory(MemorySystem):
    """Keep a wide set of examples but compact near-duplicate same-answer items."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, Any]] = []
        self._last_context_chars = 0

    def _add_example(self, question: str, target: str) -> None:
        signature = _signature(question)
        for item in self.examples:
            if item["target"] != target:
                continue
            previous = _signature(item["question"])
            union = len(signature | previous)
            similarity = len(signature & previous) / union if union else 1.0
            if similarity >= 0.92:
                item["support"] = int(item.get("support", 1)) + 1
                return
        self.examples.append({"question": question, "target": target, "support": 1})
        if len(self.examples) > 512:
            self.examples = self.examples[-512:]

    def _coverage_order(self) -> list[dict[str, Any]]:
        groups: dict[str, list[dict[str, Any]]] = defaultdict(list)
        first_seen: dict[str, int] = {}
        for index, item in enumerate(self.examples):
            target = item["target"]
            if target not in first_seen:
                first_seen[target] = index
            groups[target].append(item)

        target_order = sorted(groups, key=lambda target: (len(groups[target]), first_seen[target]))
        selected: list[dict[str, Any]] = []
        depth = 0
        while len(selected) < _MAX_EXAMPLES:
            added = False
            for target in target_order:
                if depth < len(groups[target]):
                    selected.append(groups[target][depth])
                    added = True
                    if len(selected) >= _MAX_EXAMPLES:
                        break
            if not added:
                break
            depth += 1
        return selected

    def _format_examples(self) -> str:
        parts: list[str] = []
        used = 0
        for index, item in enumerate(self._coverage_order(), start=1):
            part = f"Reference {index}\nProblem: {item['question']}\nExpected answer: {item['target']}"
            added = len(part) + (2 if parts else 0)
            if used + added > _MAX_CONTEXT_CHARS:
                continue
            parts.append(part)
            used += added
        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples = self._format_examples()
        self._last_context_chars = len(examples)
        response = self.call_llm(
            _PROMPT.format(examples=examples or "No references yet.", input=input)
        )
        answer = extract_json_field(response, "final_answer")
        return answer, {"full_response": response, "num_examples": examples.count("Reference ")}

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            self._add_example(
                _question_from_result(result), str(result.get("ground_truth", ""))
            )
        self._last_context_chars = 0

    def get_context_length(self) -> int:
        return self._last_context_chars or len(self._format_examples())

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = [
            {
                "question": str(item.get("question", "")),
                "target": str(item.get("target", "")),
                "support": int(item.get("support", 1)),
            }
            for item in data.get("examples", [])
        ][-512:]
        self._last_context_chars = 0
