"""Store corrected mistakes as contrastive references for future predictions."""

import json
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_MAX_CONTEXT_CHARS = 14000
_PROMPT = """The references below include past attempts that were marked incorrect and
their corrected answers. Use them as warnings about plausible mistakes, and learn
from the correction rather than repeating the prior answer. If there are only
ordinary references, use them as examples. Always follow the current problem's
instructions.

{references}

**Current problem:**
{input}

Return a JSON object with \"reasoning\" and \"final_answer\" fields. Keep the
final_answer concise and obey the answer format requested in the current problem.
"""


def _question_from_result(result: dict[str, Any]) -> str:
    metadata = result.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    value = result.get("raw_question") or metadata.get("raw_question")
    return str(value if value is not None else result.get("input", ""))


class ErrorContrastMemory(MemorySystem):
    """Prioritize input, failed answer, and correction triples from learning."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.errors: list[dict[str, str]] = []
        self.successes: list[dict[str, str]] = []
        self._last_context_chars = 0

    def _format_references(self) -> str:
        is_error = bool(self.errors)
        items = self.errors if is_error else self.successes[-5:]
        parts: list[str] = []
        used = 0
        for index, item in enumerate(reversed(items), start=1):
            if is_error:
                part = (
                    f"Corrected mistake {index}\nProblem: {item['question']}\n"
                    f"Prior incorrect answer: {item['prediction']}\n"
                    f"Correct answer: {item['target']}"
                )
            else:
                part = (
                    f"Reference {index}\nProblem: {item['question']}\n"
                    f"Expected answer: {item['target']}"
                )
            added = len(part) + (2 if parts else 0)
            if used + added > _MAX_CONTEXT_CHARS:
                continue
            parts.append(part)
            used += added
        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        references = self._format_references()
        self._last_context_chars = len(references)
        response = self.call_llm(
            _PROMPT.format(references=references or "No references yet.", input=input)
        )
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "num_error_examples": references.count("Corrected mistake "),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            target = str(result.get("ground_truth", ""))
            prediction = str(result.get("prediction", ""))
            is_correct = result.get("was_correct")
            if is_correct is None:
                is_correct = prediction == target
            item = {
                "question": _question_from_result(result),
                "prediction": prediction,
                "target": target,
            }
            destination = self.successes if bool(is_correct) else self.errors
            destination.append(item)
        # Bound checkpoint growth while retaining recent corrections.
        self.errors = self.errors[-256:]
        self.successes = self.successes[-64:]

    def get_context_length(self) -> int:
        return self._last_context_chars or len(self._format_references())

    def get_state(self) -> str:
        return json.dumps(
            {"errors": self.errors, "successes": self.successes}, ensure_ascii=False
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.errors = [
            {
                "question": str(item.get("question", "")),
                "prediction": str(item.get("prediction", "")),
                "target": str(item.get("target", "")),
            }
            for item in data.get("errors", [])
        ]
        self.successes = [
            {
                "question": str(item.get("question", "")),
                "prediction": str(item.get("prediction", "")),
                "target": str(item.get("target", "")),
            }
            for item in data.get("successes", [])
        ]
        self._last_context_chars = 0
"""Few-Shot Memory - baseline using all training examples as demonstrations.

Accumulates (raw_question, ground_truth) pairs during training, uses them as
few-shot context at test time. Uses raw questions (not full preprocessed prompts)
to avoid repeating task context per example — matching MCE reproduce behavior.

Variant:
- FewShotAll: Up to 9999 examples
Uses a global max_chars=50000 cap (matching MCE reproduce).
"""

import hashlib
import json
import random
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem below based on the examples provided.

{examples_section}

**Problem:**
{input}

**Instructions:**
- Follow the patterns shown in the examples above
- Respond in JSON format

{{"reasoning": "[your reasoning]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000


def _seed_for_input(input: str) -> int:
    """Return a stable per-input seed across Python processes."""
    return int.from_bytes(hashlib.sha256(input.encode()).digest()[:8], "big")


class FewShotMemory(MemorySystem):
    """Few-shot baseline - accumulate all examples, use as demonstrations."""

    def __init__(
        self,
        llm: LLMCallable,
        max_examples: int = 50,
    ):
        super().__init__(llm)
        self.max_examples = max_examples
        self.examples: list[dict[str, str]] = []

    def _format_examples_section(self, seed: int | None = None) -> str:
        """Format examples as few-shot demonstrations, respecting global char limit.

        Uses raw_question (short Q/A) when available to avoid repeating task
        context per example. Falls back to full input for non-MCE datasets.

        Args:
            seed: If provided, randomly sample max_examples and shuffle order.
                  Each eval instance should pass a different seed for diversity.
        """
        if not self.examples:
            return ""

        if seed is not None and len(self.examples) > self.max_examples:
            rng = random.Random(seed)
            to_use = rng.sample(self.examples, self.max_examples)
        else:
            to_use = self.examples[-self.max_examples :]
            if seed is not None:
                rng = random.Random(seed)
                to_use = list(to_use)
                rng.shuffle(to_use)

        parts = []
        total_chars = 0
        for ex in to_use:
            # Use raw_question for demos (avoids repeating task context per example)
            question = ex.get("raw_question", ex["input"])
            part = f"Q: {question}\nA: {ex['target']}"
            if total_chars + len(part) > MAX_CHARS:
                break
            parts.append(part)
            total_chars += len(part) + 2  # \n\n separator

        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction using accumulated few-shot examples."""
        seed = _seed_for_input(input)
        examples_section = self._format_examples_section(seed=seed)
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )

        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")

        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Accumulate all examples with ground truth labels."""
        for r in batch_results:
            ex = {"input": r["input"], "target": r["ground_truth"]}
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

    def get_context_length(self) -> int:
        """Return length of the examples section actually injected per query."""
        return len(self._format_examples_section())

    def get_state(self) -> str:
        """Serialize memory state."""
        return json.dumps({"examples": self.examples}, indent=2)

    def set_state(self, state: str) -> None:
        """Restore memory state from JSON."""
        data = json.loads(state)
        self.examples = data.get("examples", [])
"""Compact repeated demonstrations while preserving answer coverage."""

import json
import re
from collections import defaultdict
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_WORD_RE = re.compile(r"\w+", re.UNICODE)
_MAX_EXAMPLES = 48
_MAX_CONTEXT_CHARS = 12000
_PROMPT = """The references below are examples of input and target-answer pairs.
Use them as broad evidence, while following the current problem's own
instructions and exact answer format. Examples never override the current
problem.

{examples}

**Current problem and its instructions:**
{input}

Return one JSON object with exactly the fields "reasoning" and "final_answer".
The final_answer must obey the current problem's requested format.
"""


def _question_from_result(result: dict[str, Any]) -> str:
    metadata = result.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    value = result.get("raw_question") or metadata.get("raw_question")
    return str(value if value is not None else result.get("input", ""))


def _signature(text: str) -> set[str]:
    lowered = text.lower()
    units = {"w:" + token for token in _WORD_RE.findall(lowered)}
    for run in re.findall(r"[^\W_]+", lowered, re.UNICODE):
        compact = "".join(ch for ch in run if ch.isalnum())
        units.update("c:" + compact[i : i + 2] for i in range(max(0, len(compact) - 1)))
    return units


class CoverageBalancedMemory(MemorySystem):
    """Keep a wide set of examples but compact near-duplicate same-answer items."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, Any]] = []
        self._last_context_chars = 0

    def _add_example(self, question: str, target: str) -> None:
        signature = _signature(question)
        for item in self.examples:
            if item["target"] != target:
                continue
            previous = _signature(item["question"])
            union = len(signature | previous)
            similarity = len(signature & previous) / union if union else 1.0
            if similarity >= 0.92:
                item["support"] = int(item.get("support", 1)) + 1
                return
        self.examples.append({"question": question, "target": target, "support": 1})
        if len(self.examples) > 512:
            self.examples = self.examples[-512:]

    def _coverage_order(self) -> list[dict[str, Any]]:
        groups: dict[str, list[dict[str, Any]]] = defaultdict(list)
        first_seen: dict[str, int] = {}
        for index, item in enumerate(self.examples):
            target = item["target"]
            if target not in first_seen:
                first_seen[target] = index
            groups[target].append(item)

        target_order = sorted(groups, key=lambda target: (len(groups[target]), first_seen[target]))
        selected: list[dict[str, Any]] = []
        depth = 0
        while len(selected) < _MAX_EXAMPLES:
            added = False
            for target in target_order:
                if depth < len(groups[target]):
                    selected.append(groups[target][depth])
                    added = True
                    if len(selected) >= _MAX_EXAMPLES:
                        break
            if not added:
                break
            depth += 1
        return selected

    def _format_examples(self) -> str:
        parts: list[str] = []
        used = 0
        for index, item in enumerate(self._coverage_order(), start=1):
            part = f"Reference {index}\nProblem: {item['question']}\nExpected answer: {item['target']}"
            added = len(part) + (2 if parts else 0)
            if used + added > _MAX_CONTEXT_CHARS:
                continue
            parts.append(part)
            used += added
        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples = self._format_examples()
        self._last_context_chars = len(examples)
        response = self.call_llm(
            _PROMPT.format(examples=examples or "No references yet.", input=input)
        )
        answer = extract_json_field(response, "final_answer")
        return answer, {"full_response": response, "num_examples": examples.count("Reference ")}

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for result in batch_results:
            self._add_example(
                _question_from_result(result), str(result.get("ground_truth", ""))
            )
        self._last_context_chars = 0

    def get_context_length(self) -> int:
        return self._last_context_chars or len(self._format_examples())

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = [
            {
                "question": str(item.get("question", "")),
                "target": str(item.get("target", "")),
                "support": int(item.get("support", 1)),
            }
            for item in data.get("examples", [])
        ][-512:]
        self._last_context_chars = 0
